package local.lito381.server;
import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** NPC skill target plan released only after the existing player HP event accepts. */
final class NativeSourceNpcMagicEffects {
 static final String P="local/lito381/server/";
 record Source(GameHub hub,long room,Object owner,Object actor,Object life,Object generation,long id,int kind,NativePlayerLifetime lifetime,int max){}
 static final class After {final NativeSourceRawDamage.Member target;final Source source;final int heal;final BattleEraseMagicStatus status;final BattleEraseMagicStatus.Lease erase;final NativePlayerLifetime lifetime;final AtomicBoolean claimed=new AtomicBoolean();After(NativeSourceRawDamage.Member target,Source source,int heal,BattleEraseMagicStatus status,BattleEraseMagicStatus.Lease erase,NativePlayerLifetime lifetime){this.target=target;this.source=source;this.heal=heal;this.status=status;this.erase=erase;this.lifetime=lifetime;}}
 record Output(Source source,ClientSession pc,NativePlayerCommit.Binding binding,int ratio){}
 static boolean drainingSkill(int skill){return skill==10||skill==28;}
 static int capped(int max,int hp,int heal){return(int)Math.min((long)max,(long)hp+(long)heal);}
 static int ratio(int hp,int max){return max<=0?100:(int)Math.max(0,Math.min(100,100L*hp/max));}
 static void damage(ClientSession pc,int amount,ClientSession caster,boolean magic,BattleTimeAttackMagicSkillCatalog.Definition definition)throws IOException{
  var value=NativeCombatAttacker.nativeSourceNpcPlayerCurrent();if(!(value instanceof NativeSourceNpcPlayer.Scope scope)){NativeSourceNpcPlayer.damage(pc,amount,caster,magic);return;}var previous=CombatAccess.field(scope,"nativeSourceNpcMagicDefinition");CombatAccess.set(scope,"nativeSourceNpcMagicDefinition",definition);try{NativeSourceNpcPlayer.damage(pc,amount,caster,magic);}finally{CombatAccess.set(scope,"nativeSourceNpcMagicDefinition",previous);}
 }
 static boolean suppressLegacy(GameHub hub,long room,long id){var value=NativeCombatAttacker.nativeSourceNpcPlayerCurrent();return CombatRules.loaded()&&value!=null&&(!(value instanceof NativeSourceNpcPlayer.Scope scope)||scope.origin().hub()==hub&&scope.origin().room()==room&&scope.attacker().id()==id);}
 static BattleQuestEncounter.Healing legacyQuest(GameHub hub,long room,ClientSession pc,long id,int amount){return suppressLegacy(hub,room,id)?null:hub.healQuestMonster(room,pc,id,amount);}
 static BattleTimeAttackEncounter.Healing legacyTime(GameHub hub,long room,ClientSession pc,long id,int amount){return suppressLegacy(hub,room,id)?null:hub.healTimeAttackActor(room,pc,id,amount);}
 static Object actor(Object owner,long id,int kind){return CombatAccess.call(owner,"monster","(J)L"+P+(kind==3?"BattleQuestEncounter":"BattleTimeAttackEncounter")+"$Monster;",id);}
 static Source source(NativeSourceNpcPlayer.Scope scope){var ref=scope.attacker();if(ref.kind()!=3&&ref.kind()!=4)return null;var hub=scope.origin().hub();synchronized(hub){var room=((Map<?,?>)CombatAccess.field(hub,"rooms")).get(ref.room());if(room==null)return null;var owner=CombatAccess.field(room,ref.kind()==3?"questEncounter":"timeAttackEncounter");if(owner==null)return null;synchronized(owner){var actor=actor(owner,ref.id(),ref.kind());if(actor==null||NativeSourceArenaPoison.rawLife(actor)!=ref.owner()||(int)CombatAccess.field(actor,"hp")<=0)return null;var snapshot=CombatAccess.call(actor,"snapshot","()L"+P+(ref.kind()==3?"BattleQuestEncounter":"BattleTimeAttackEncounter")+"$Snapshot;");return new Source(hub,ref.room(),owner,actor,ref.owner(),NativeProcHealingEncounter.generation(owner),ref.id(),ref.kind(),scope.lifetime(),(int)CombatAccess.call(snapshot,"maxHp","()I"));}}}
 static boolean sourceCurrent(Source source){return source!=null&&source.lifetime().mode!=NativePlayerLifetime.Mode.STOPPED&&!(boolean)CombatAccess.field(source.hub(),"nativeStaticMotionClosed")&&CombatAccess.field(source.owner(),"sourceProcEncounterGeneration")==source.generation()&&NativeSourceArenaPoison.rawLife(source.actor())==source.life()&&(int)CombatAccess.field(source.actor(),"hp")>0;}
 static void bind(NativeSourceDamageDisplay.Plan plan,NativeSourceNpcPlayer.Scope scope,ClientSession pc,int damage,boolean magic){
  var value=CombatAccess.field(scope,"nativeSourceNpcMagicDefinition");if(!magic||damage<=0||!(value instanceof BattleTimeAttackMagicSkillCatalog.Definition definition)||scope!=NativeCombatAttacker.nativeSourceNpcPlayerCurrent()||!pc.nativePlayerActionLock().isHeldByCurrentThread())return;var member=scope.origin().members().get(pc);if(member==null||plan.nativeRawGuard==null||plan.nativeRawGuard.target()!=member)return;var row=NativeSkillTargetMetadata.row(definition.skillId());boolean attack=row!=null&&row.type()==64;var status=(BattleEraseMagicStatus)CombatAccess.field(pc,"eraseMagicStatus");var lease=attack?status.capture(System.nanoTime()):null;var erase=lease!=null&&lease.present()?lease:null;int heal=drainingSkill(definition.skillId())?damage:0;plan.nativeSourceNpcMagicAfter=new After(member,heal>0?source(scope):null,heal,status,erase,scope.lifetime());
 }
 static boolean claim(After after,boolean accepted){return after!=null&&accepted&&after.claimed.compareAndSet(false,true);}
 static void accepted(NativePlayerCommit.Frame frame){var plan=frame.event.sourceDisplay();if(plan==null||!(plan.nativeSourceNpcMagicAfter instanceof After after)||!Objects.equals(frame.event.target(),after.target.binding)||!claim(after,frame.accepted))return;
  try{if(after.heal>0&&after.source!=null)heal(after.source,after.heal);}catch(RuntimeException failure){NativeSourcePhysicalNpc.failed(after.lifetime);}
  if(frame.fatal||after.erase==null)return;try{var pc=after.target.pc;NativeSourcePlayerActionLock.runPairOrdered(pc,pc,()->{synchronized(after.lifetime.admission){if(after.lifetime.mode!=NativePlayerLifetime.Mode.STOPPED&&!(boolean)CombatAccess.field(plan.hub,"nativeStaticMotionClosed")&&after.target.current(false)&&NativeSourceDamageDisplay.n(pc,"playerHp")>0)after.status.consume(after.erase);}});}catch(RuntimeException failure){NativeSourcePhysicalNpc.failed(after.lifetime);}
 }
 static void heal(Source source,int heal){Object result;synchronized(source.lifetime().admission){if(!sourceCurrent(source))return;synchronized(source.hub()){var room=((Map<?,?>)CombatAccess.field(source.hub(),"rooms")).get(source.room());if(room==null||CombatAccess.field(room,source.kind()==3?"questEncounter":"timeAttackEncounter")!=source.owner())return;synchronized(source.owner()){if(!sourceCurrent(source)||actor(source.owner(),source.id(),source.kind())!=source.actor())return;result=CombatAccess.call(source.actor(),"nativeSourceNpcMagicHeal","(I)L"+P+(source.kind()==3?"BattleQuestEncounter":"BattleTimeAttackEncounter")+"$Healing;",heal);}}}if(result!=null&&(int)CombatAccess.call(result,"restoredHp","()I")>0)meters(source);}
 static void meters(Source source){if(!sourceCurrent(source)||!NativeSourceOtherControls.settings().hpbar())return;var cache=(NativeSourceMonsterHp.Cache)CombatAccess.field(source.actor(),"nativeSourceHpViewers");List<NativeSourceMonsterHp.Viewer> viewers;synchronized(cache){if(cache.life!=source.life())return;viewers=List.copyOf(cache.viewers.values());}int ratio=ratio((int)CombatAccess.field(source.actor(),"hp"),source.max());for(var entry:viewers){var pc=entry.pc().get();if(pc==null||entry.ratio()==ratio)continue;var out=new Output(source,pc,entry.binding(),ratio);NativePlayerCommit.completionFrame(null,()->send(out));}}
 static boolean current(Output out){var source=out.source();return sourceCurrent(source)&&NativeSourceOtherControls.settings().hpbar()&&NativeAcceptedFreezeMutation.roleFrame(out.binding(),out.pc())&&!(boolean)CombatAccess.field(out.pc(),"sourceItemDisconnected")&&out.binding().phase().equals("BATTLE")&&out.binding().room()==source.room()&&CombatAccess.field(out.pc(),"hub")==source.hub()&&ratio((int)CombatAccess.field(source.actor(),"hp"),source.max())==out.ratio()&&BattleSpellCatalog.isInNativeScreen(NativeSourceDamageDisplay.n(out.pc(),"positionX"),NativeSourceDamageDisplay.n(out.pc(),"positionY"),(int)CombatAccess.field(source.actor(),"x"),(int)CombatAccess.field(source.actor(),"y"));}
 static void send(Output out){if(!current(out))return;var previous=NativeAreaMaterialAction.current.get();NativeAreaMaterialAction.current.remove();try{var c=new NativeAreaMaterialAction.Context(out.pc());c.nativeSourceCubeStatusProof=out;try{NativeAreaMaterialAction.owned(c,()->{synchronized(out.pc()){if(current(out))out.pc().nativeSelfOriginalSend(Protocol.hitRatio(out.source().id(),out.ratio(),100),"S_HIT_RATIO Source accepted NPC drain heal");}});}finally{c.nativeSourceCubeStatusProof=null;}}catch(IOException|RuntimeException failure){NativeSourcePhysicalNpc.failed(out.source().lifetime());}finally{if(previous==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(previous);}}
 static Object marker(){var context=NativeAreaMaterialAction.current.get();return context==null?null:context.nativeSourceCubeStatusProof;}
 static boolean packet(Output out,byte[]packet){return packet!=null&&packet.length==6&&(packet[0]&255)==Protocol.S_HIT_RATIO&&NativeSourcePhysicalNpc.object(packet)==out.source().id()&&(packet[5]&255)==out.ratio();}
 static boolean allowFrame(ClientSession pc,byte[]packet){return !(marker()instanceof Output out)||out.pc()==pc&&current(out)&&packet(out,packet);}
 static void sent(ClientSession pc,byte[]packet){if(!(marker()instanceof Output out)||out.pc()!=pc||!packet(out,packet))return;var cache=(NativeSourceMonsterHp.Cache)CombatAccess.field(out.source().actor(),"nativeSourceHpViewers");synchronized(cache){if(cache.life!=out.source().life())return;var old=cache.viewers.get(out.binding().object());if(old!=null&&old.pc().get()==pc&&old.binding().equals(out.binding()))cache.viewers.put(out.binding().object(),new NativeSourceMonsterHp.Viewer(old.pc(),old.binding(),out.ratio()));}}
 private NativeSourceNpcMagicEffects(){}
}
